-- public.floor_greening(p_world uuid, p_x integer, p_y integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.floor_greening(p_world uuid, p_x integer, p_y integer)
 RETURNS floor_tile
 LANGUAGE sql
 STABLE
AS $function$
  select f.* from floor_tile f join build_material_def m on m.id = f.material and m.kind = 'stone'
   where f.world_id = p_world and f.x = p_x and f.y = p_y and bill_done(f.needed) and coalesce(f.kind, 'floor') = 'floor'
     and not exists (select 1 from floor_tile o where o.world_id = p_world and o.x = p_x and o.y = p_y and o.level = f.level + 1)
   order by f.level desc limit 1
$function$
